    def __init__(
        self,
        in_channels,
        out_channels,
        kernel_size,
        stride=1,
        padding=0,
        dilation=1,
        bias=False,
    ):
        super().__init__()
        self.conv1d_transpose = nn.ConvTranspose1d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            dilation=dilation,
            bias=bias,
        )
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride_val = stride
        self.padding_val = padding
        self.dilation_val = dilation
        self._packed = False

    def _pack_weights(self):
        device = torch.device("cpu")
        w = self.conv1d_transpose.weight.data.detach()
        self.weight_kio = w.permute(2, 0, 1).contiguous().to(device, torch.float16)
        self._packed = True

    def forward(self, x):
        if not self._packed:
            self._pack_weights()

        device = torch.device("cpu")
        x = x.to(device, torch.float16)
